#include <iostream>
using namespace std;

int main() {
    int a, b;
    cin >> a >> b;

    // / 和 % 都是整数运算：
    // / 只留整数部分（向零截断，不是向下取整），
    // % 留下除不尽的那部分，余数的符号跟着被除数 a。
    int q = a / b;
    int r = a % b;

    cout << q << endl;
    cout << r << endl;
    return 0;
}

