#include <iostream>
using namespace std;

int main() {
    int a, b;
    cin >> a >> b;

    // 关键在顺序：&& 从左往右算且会短路。
    // b == 0 时左边 b != 0 已经是假，&& 的结果必定是假，
    // 右边的 a % b 根本不会执行，所以不会触发整数除零崩溃。
    if (b != 0 && a % b == 0) {
        cout << "yes" << endl;
    } else {
        cout << "no" << endl;
    }
    return 0;
}

