#include <iostream>
using namespace std;

int main() {
    int a, b;
    cin >> a >> b;

    // 位运算 = 「按二进制每一位单独算」，和逻辑运算 && || 毫无关系。
    cout << (a & b) << endl;    // 逐位与：两位都是 1 才得 1
    cout << (a | b) << endl;    // 逐位或：有一位是 1 就得 1
    cout << (a ^ b) << endl;    // 逐位异或：两位不同才得 1
    cout << ~a << endl;         // 单目取反：恒等于 -a - 1，所以结果带负号
    // 下面两行括号不能省：<< 是左结合的，写 cout << a << 1 会先输出 a 再输出 1。
    cout << (a << 1) << endl;   // 左移一位 = 乘 2
    cout << (b >> 1) << endl;   // 右移一位 = 整除 2（本题保证 b 非负）
    return 0;
}

