#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // 后置 ++：先把 n 的旧值交给 x，n 自己再加 1。
    // 等价于 x = n; n = n + 1;
    int x = n++;
    cout << x << endl;   // 第一行：自增之前的旧值
    cout << n << endl;   // 第二行：此时 n 已经是加过 1 的值

    // 前置 ++：n 先加 1，再把新值交给 y。
    // 等价于 n = n + 1; y = n;
    int y = ++n;
    cout << y << endl;   // 第三行：自增之后的新值

    // 后置 --：先把当前值交给 z，n 再减 1。
    int z = n--;
    cout << z << endl;   // 第四行：自减之前的值
    cout << n << endl;   // 第五行：此时 n 已经减回去了
    return 0;
}

