#include <iostream>
using namespace std;

int main() {
    int a, b, c;
    cin >> a >> b >> c;

    // 第一行：* 比 + 优先，先算 b * c。
    cout << (a + b * c) << endl;

    // 第二行：括号最高，加法被提到最前面，结果通常完全不同。
    cout << ((a + b) * c) << endl;

    // 第三行：/ 和 % 同级、都比 + 高，所以先各算各的再相加。
    // 整数除法会截断，余数的符号跟着被除数，两项都可能是负数。
    cout << (a / c + b % c) << endl;

    // 第四行：式子内部 & 的优先级比 | 高，a & b | c 就等价于 (a & b) | c，
    // 这里主动把内层括号写全（写成 a & b | c 也行，但 clang -Wall 会提示
    // -Wbitwise-op-parentheses）；外层括号是因为位运算优先级低于 <<，
    // 不加的话会被解析成 (cout << a) & b | c，直接编译不过。
    cout << ((a & b) | c) << endl;
    return 0;
}

